fun sum_of_binomial_products(n: int): int {
  var s: int := 0;
  var i: int := 0;
  while i <= n {
    var c: int := 1;
    var j: int := 1;
    while j <= i {
      if j == 1 {
        c := 1;
      } else {
        c := c * (i - j + 1) / j;
      }
      j := j + 1;
    }
    s := s + c;
    i := i + 1;
  }
  return s;
}

fun binomial_coefficient(n: int, k: int): int {
  if k < 0 or k > n {
    return 0;
  }
  if k == 0 or k == n {
    return 1;
  }
  if k > n / 2 {
    return binomial_coefficient(n, n - k);
  }
  var c: int := 1;
  var i: int := 1;
  while i <= k {
    c := c * (n - i + 1) / i;
    i := i + 1;
  }
  return c;
}
